import { access, cp, rm } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const desktopRoot = fileURLToPath(new URL("..", import.meta.url));
const webDist = path.resolve(desktopRoot, "../web/dist");
const target = path.join(desktopRoot, "dist/web");

await access(path.join(webDist, "index.html"));
await rm(target, { recursive: true, force: true });
await cp(webDist, target, { recursive: true });

// Runtime app icons (the Settings icon picker), generated by scripts/generate-icons.py.
const icons = path.join(desktopRoot, "dist/icons");
await rm(icons, { recursive: true, force: true });
await cp(path.join(desktopRoot, "resources/icons"), icons, { recursive: true });
